def compute(vars):
    total_fair_value = vars["v1"]
    corporate_stocks_fair_value = vars["v2"]
    value = total_fair_value - corporate_stocks_fair_value

    return {
        "value": value,
        "trace": {
            "total_fair_value": total_fair_value,
            "corporate_stocks_fair_value": corporate_stocks_fair_value,
            "difference": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
